    """Find all connected components of 1s"""
    visited = set()
    shapes = []
    rows, cols = len(grid), len(grid[0])

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and (r,c) not in visited:
                # BFS to find connected component
                shape = []
                queue = [(r,c)]
                while queue:
                    cr, cc = queue.pop(0)
                    if (cr, cc) in visited:
                        continue
                    if cr < 0 or cr >= rows or cc < 0 or cc >= cols:
                        continue
                    if grid[cr][cc] != 1:
                        continue

                    visited.add((cr, cc))
                    shape.append((cr, cc))

                    # Add neighbors
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        ncr, ncc = cr + dr, cc + dc
                        if (ncr, ncc) not in visited and grid[ncr][ncr] == 1:
                            queue.append((ncr, ncc))

    return shapes

